func TestCountEven(t *testing.T) {
	cases := []struct {
		name string
		nums []int
		want int
	}{
		{"empty", nil, 0},
		{"positive", []int{1, 2, 3, 4}, 2},
		{"negative and zero", []int{-3, -2, 0, 5}, 2},
		{"all odd", []int{1, 3, 5}, 0},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := countEven(tc.nums); got != tc.want {
				t.Fatalf("countEven(%v) = %d, want %d", tc.nums, got, tc.want)
			}
		})
	}
}

